export default async function run({execution_id, input, data, store, db}) {

  /**
   * Декодирует контент из GitHub API ответа
   * Поддерживает оба формата:
   * - Raw text (если Accept: application/vnd.github.raw)
   * - JSON с Base64 (если Accept: application/json)
   */
  function decodeGitHubContent(rawData) {
    if (!rawData) return '';
    const base64Clean = rawData.content.replace(/\n/g, '');
    return Buffer.from(base64Clean, 'base64').toString('utf-8');
  }

  const content = decodeGitHubContent(JSON.parse(data["{{$17.result}}"]));
  return { content };
}

